self.onInit = function () {
    const TAILWIND_ID = 'tailwindcss';

    // Check if Tailwind is already injected
    if (!document.getElementById(TAILWIND_ID)) {
        const script = document.createElement('script');
        script.id = TAILWIND_ID;
        script.src = 'https://cdn.tailwindcss.com';
        script.onload = function () {
            console.log('[TB Widget] ✅ Tailwind loaded');
            // Trigger a re-render after Tailwind loads
            self.ctx.detectChanges();
        };
        document.head.appendChild(script);
    } else {
        console.log('[TB Widget] ⚠️ Tailwind already loaded');
        self.ctx.detectChanges();
    }

    // Optional: You can initialize widget variables here
    self.temperature = '---';
    self.humidity = '---';

    self.onDataUpdated = function () {
        const data = self.ctx.data;
        data.forEach(dp => {
            if (dp.data.length > 0) {
                const latest = dp.data[dp.data.length - 1][1];
                if (dp.dataKey.name === 'temperature') {
                    self.temperature = latest;
                } else if (dp.dataKey.name === 'humidity') {
                    self.humidity = latest;
                }
            }
        });
    };
};

